import os


def iter_lines(path: str):
    # A generator: one line in memory at a time. The file object
    # itself is an iterator (buffered reads), and wrapping it lets
    # us add per-line processing lazily.
    with open(path, "r", encoding="utf-8") as fh:
        for raw in fh:
            line = raw.strip()
            if line:  # skip empties as we stream
                yield line


def build_report(path: str) -> dict[str, int]:
    unique: set[str] = set()
    total = 0
    # Peak memory is bounded by the set of unique strings only;
    # the stream never materializes the whole file.
    for line in iter_lines(path):
        unique.add(line)
        total += 1
    return {"total": total, "unique": len(unique)}


if __name__ == "__main__":
    path = "access.log"
    if not os.path.exists(path):
        with open(path, "w", encoding="utf-8") as fh:
            fh.write("GET / 200\nGET / 200\nPOST /api 201\n")
    print(build_report(path))
